import{_ as t,o,c as i,a3 as a}from"./chunks/framework.BveOjhN0.js";const m=JSON.parse('{"title":"Opportunities Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Opportunities Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/opportunities-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Opportunities Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/opportunities-overview"}]]},"headers":[],"relativePath":"user-guide/opportunities-overview.md","filePath":"user-guide/opportunities-overview.md","lastUpdated":1785453370000}'),r={name:"user-guide/opportunities-overview.md"};function n(d,e,s,l,p,c){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="opportunities-module" tabindex="-1">Opportunities Module <a class="header-anchor" href="#opportunities-module" aria-label="Permalink to &quot;Opportunities Module&quot;">​</a></h1><p>Sales deals module on the frozen platform. Mirrors the <a href="/user-guide/leads-overview">Leads</a> pipeline UX (stages + Kanban board + table) and the <a href="/user-guide/activities-overview">Activities</a> / Contacts / Companies reference architecture for notes, assignment, and soft related links.</p><p><strong>Sales Pipeline</strong> is delivered <strong>inside</strong> Opportunities — stages and the Kanban board are not a separate Marketplace SKU.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/opportunities">opportunities.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/opportunities">opportunities-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/opportunities">opportunities-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/leads-overview">leads.md</a> · <a href="/user-guide/activities-overview">activities.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-opportunities">../api/tenant-v1-opportunities.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Deal fields: name (required), optional amount / currency / probability / expected close date</li><li>Pipeline stages (seeded: Prospecting → Qualification → Proposal → Negotiation → Won / Lost)</li><li><strong>Kanban board (default)</strong> + table view; stage changes via <code>POST /opportunities/{id}/stage</code></li><li>KPIs via <code>GET /opportunities/stats</code>; board via <code>GET /opportunities/board</code></li><li>Soft optional links: Contact / Company / Lead (FK rejected when that module is not installed)</li><li>Assignment with assignee scoping via <code>opportunities.assign</code></li><li>Notes + domain activity timeline</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:opportunities</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Sales category)</li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>opportunities.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Opportunities from Marketplace (free). Catalog: slug <code>opportunities</code>, category <code>sales</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 40</code>. Only Leads and Tasks install automatically on new workspaces.</p><h2 id="related-modules-optional" tabindex="-1">Related modules (optional) <a class="header-anchor" href="#related-modules-optional" aria-label="Permalink to &quot;Related modules (optional)&quot;">​</a></h2><p>No hard <code>module_dependencies</code> row today. Linking a Contact, Company, or Lead requires that module to be entitled; otherwise validation rejects the FK.</p><p><strong>Planned hard dependencies (future):</strong> Quotations and Contracts are expected to depend on Opportunities when those Sales modules ship — see <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Separate Marketplace SKU for “Sales Pipeline” (pipeline lives in this module)</li><li>Custom stage admin UI (stages are seeded / idempotent seeder)</li><li>Lead → Opportunity conversion wizard</li><li>Quotations / Contracts integration</li><li>Real-time board sync (Reverb / Echo)</li><li>Export / import</li></ul>',15)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
